import kotlinx.coroutines.*

suspend fun step(n: Int): Int {
    delay(10)
    return n * 2
}

fun main() = runBlocking {
    val first = step(1)
    val second = async { step(first) }
    val third = step(second.await())
    println("$first $third")
    try {
        check(third > 10) { "мало" }
    } catch (e: IllegalStateException) {
        println("Ошибка: ${e.message}")
    }
}
